insert into public.courses (slug, title, category, icon, short_description, description, duration, price, currency, tutor_id, image_url, outcomes, requirements, faqs, assessment_info, certificate_info, featured, published, sort_order) values ('introduction-to-cybersecurity', 'Introduction to Cybersecurity', 'Security', 'shield', 'Understand common threats and learn to protect accounts, devices and small organisations.', 'Learn how attacks work and how to defend against them. Topics include network basics, phishing, password and account security, and simple incident response.', '8 weeks', 80000, 'NGN', (select id from public.tutors where slug = 'ibrahim-lawal'), 'assets/images/courses/introduction-to-cybersecurity.svg', '["Recognise phishing and social engineering","Secure accounts and devices","Explain core security concepts","Draft a simple security policy for a small team"]'::jsonb, '["Basic computer skills"]'::jsonb, '[{"q":"Do I need prior experience?","a":"No. Every programme starts from the basics unless the requirements say otherwise."},{"q":"How do I pay and get access?","a":"Enrol on this page, then complete payment. Lessons unlock only after your payment has been verified."},{"q":"Can I study on my phone?","a":"Yes. The learning platform works on phones, tablets and laptops."},{"q":"How do I get my certificate?","a":"Finish all lessons, assignments and examinations. Your certificate then appears in your dashboard."}]'::jsonb, 'Assessment combines weekly assignments and a final examination. To be eligible for a certificate you complete every lesson, submit every assignment and pass each examination (pass mark 50%).', 'On completion you receive a Courssins Technology Institute certificate with a unique number that anyone can check on our public verification page.', true, true, 9) on conflict (slug) do nothing;
